import { createClient } from '@supabase/supabase-js';
import type { Database } from '@/integrations/supabase/types';

// A short-lived, second auth client used ONLY to run one browser-based
// sign-in (or account connection) with PKCE, then hand the result to the
// app's real client with setSession().
//
// Why not the main client: src/integrations/supabase/client.ts is
// generated by Lovable (and overwritten by it), and uses the implicit
// flow, which returns tokens in the redirect URL. PKCE returns a one-time
// code instead, which is useless without the verifier kept here.
//
// Safety rules this client follows:
//   - its own storage key, so it never touches the main session;
//   - sessionStorage, so the verifier survives the website's full-page
//     redirect but never outlives the tab;
//   - autoRefreshToken off, so it can never rotate (and so invalidate) the
//     refresh token the main client is about to take over;
//   - detectSessionInUrl off, so it ignores whatever URL it's created on;
//   - never signOut(): that would revoke the very session just handed over.
//     clearPkceStorage() just forgets everything it stored.

export const PKCE_STORAGE_KEY = 'afiyeat-social-auth';

const memory = new Map<string, string>();

function sessionStore() {
  return {
    getItem(key: string): string | null {
      try {
        return window.sessionStorage.getItem(key);
      } catch {
        return memory.get(key) ?? null;
      }
    },
    setItem(key: string, value: string): void {
      try {
        window.sessionStorage.setItem(key, value);
      } catch {
        memory.set(key, value);
      }
    },
    removeItem(key: string): void {
      try {
        window.sessionStorage.removeItem(key);
      } catch {
        /* fall through to memory */
      }
      memory.delete(key);
    },
  };
}

export function createPkceClient() {
  return createClient<Database>(
    import.meta.env.VITE_SUPABASE_URL,
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
    {
      auth: {
        flowType: 'pkce',
        storageKey: PKCE_STORAGE_KEY,
        storage: sessionStore(),
        persistSession: true,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    },
  );
}

/**
 * Forgets the helper's copy of a session but keeps the PKCE verifier, so a
 * signed-in session isn't left in sessionStorage across a page redirect.
 */
export function forgetPkceSession(): void {
  for (const key of [PKCE_STORAGE_KEY, `${PKCE_STORAGE_KEY}-user`]) {
    try {
      window.sessionStorage.removeItem(key);
    } catch {
      /* fall through to memory */
    }
    memory.delete(key);
  }
}

/** Forgets the verifier and any session copy the helper client stored. */
export function clearPkceStorage(): void {
  try {
    const keys: string[] = [];
    for (let i = 0; i < window.sessionStorage.length; i++) {
      const key = window.sessionStorage.key(i);
      if (key && key.startsWith(PKCE_STORAGE_KEY)) keys.push(key);
    }
    keys.forEach((key) => window.sessionStorage.removeItem(key));
  } catch {
    /* sessionStorage unavailable: only memory was used */
  }
  for (const key of Array.from(memory.keys())) {
    if (key.startsWith(PKCE_STORAGE_KEY)) memory.delete(key);
  }
}
